(window.__qhadithX=window.__qhadithX||{})[36]={"12":[{"c":"Sahih Bukhari","r":"Hadith 655","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-655","x":"Narrated Humaid:\n\nAnas said, \"The Prophet (ﷺ) said, 'O Bani Salima! Don't you think that for every step of yours (that you take towards the mosque) there is a reward (while coming for prayer)?\" Mujahid said: \"Regarding Allah's Statement: \"We record that which they have sent before (them), and their traces\" (36.12). 'Their traces' means 'their steps.' \" And Anas said that the people of Bani Salima wanted to shift to a place near the Prophet (ﷺ) but Allah's Messenger (ﷺ) disliked the idea of leaving their houses uninhabited and said, \"Don't you think that you will get the reward for your footprints.\" Mujahid said, \"Their foot prints mean their foot steps and their going on foot.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ حَوْشَبٍ، قَالَ حَدَّثَنَا عَبْدُ الْوَهَّابِ، قَالَ حَدَّثَنَا حُمَيْدٌ، عَنْ أَنَسٍ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ يَا بَنِي سَلِمَةَ أَلاَ تَحْتَسِبُونَ آثَارَكُمْ ‏\"‏‏.‏ وَقَالَ مُجَاهِدٌ فِي قَوْلِهِ ‏{‏وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ‏}‏ قَالَ خُطَاهُمْ‏.‏ وَقَالَ ابْنُ أَبِي مَرْيَمَ أَخْبَرَنَا يَحْيَى بْنُ أَيُّوبَ، حَدَّثَنِي حُمَيْدٌ، حَدَّثَنِي أَنَسٌ، أَنَّ بَنِي سَلِمَةَ، أَرَادُوا أَنْ يَتَحَوَّلُوا، عَنْ مَنَازِلِهِمْ، فَيَنْزِلُوا قَرِيبًا مِنَ النَّبِيِّ صلى الله عليه وسلم قَالَ فَكَرِهَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُعْرُوا ‏{‏الْمَدِينَةَ‏}‏ فَقَالَ ‏\"‏ أَلاَ تَحْتَسِبُونَ آثَارَكُمْ ‏\"‏‏.‏ قَالَ مُجَاهِدٌ خُطَاهُمْ آثَارُهُمْ أَنْ يُمْشَى فِي الأَرْضِ بِأَرْجُلِهِمْ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3226","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3226","x":"Narrated Abu Sa'eed Al-Khudri:\n\n\"Banu Salamah's dwellings were on the outskirts of Al-Madinah, so they wanted to relocate closer to the Masjid. Then this Ayah was revealed: 'Verily, We give life to the dead, and We record that which they send before (them), and their traces... (36:12)' So the Messenger of Allah (ﷺ) said: 'Your steps are recorded, so do not relocate.'\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ وَزِيرٍ الْوَاسِطِيُّ، حَدَّثَنَا إِسْحَاقُ بْنُ يُوسُفَ الأَزْرَقُ، عَنْ سُفْيَانَ الثَّوْرِيِّ، عَنْ أَبِي سُفْيَانَ، عَنْ أَبِي نَضْرَةَ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ كَانَتْ بَنُو سَلِمَةَ فِي نَاحِيَةِ الْمَدِينَةِ فَأَرَادُوا النُّقْلَةَ إِلَى قُرْبِ الْمَسْجِدِ فَنَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏إنَّا نَحْنُ نُحْيِي الْمَوْتَى وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ ‏)‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِنَّ آثَارَكُمْ تُكْتَبُ ‏فَلا يَنْتَقِلُوا‏\".‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ مِنْ حَدِيثِ الثَّوْرِيِّ وَأَبُو سُفْيَانَ هُوَ طَرِيفٌ السَّعْدِيُّ ‏.‏","v":[]}],"28":[{"c":"Sahih Bukhari","r":"Hadith 7433","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7433","x":"Narrated Abu Dharr:\n\nI asked the Prophet (ﷺ) regarding the Verse:--'And the sun runs on its fixed course for a term decreed for it.' (36.28) He said, \"Its fixed course is underneath Allah's Throne.\"","ar":"حَدَّثَنَا عَيَّاشُ بْنُ الْوَلِيدِ، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ، قَالَ سَأَلْتُ النَّبِيَّ صلى الله عليه وسلم عَنْ قَوْلِهِ ‏{‏وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا‏}‏ قَالَ ‏\"‏ مُسْتَقَرُّهَا تَحْتَ الْعَرْشِ ‏\"‏‏.‏","v":[]}],"38":[{"c":"Sahih Bukhari","r":"Hadith 3199","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3199","x":"Narrated Abu Dhar:\n\nThe Prophet (ﷺ) asked me at sunset, \"Do you know where the sun goes (at the time of sunset)?\" I replied, \"Allah and His Apostle know better.\" He said, \"It goes (i.e. travels) till it prostrates Itself underneath the Throne and takes the permission to rise again, and it is permitted and then (a time will come when) it will be about to prostrate itself but its prostration will not be accepted, and it will ask permission to go on its course but it will not be permitted, but it will be ordered to return whence it has come and so it will rise in the west. And that is the interpretation of the Statement of Allah: \"And the sun Runs its fixed course For a term (decreed). that is The Decree of (Allah) The Exalted in Might, The All- Knowing.\" (36.38)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ ـ رضى الله عنه ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم لأَبِي ذَرٍّ حِينَ غَرَبَتِ الشَّمْسُ ‏\"‏ تَدْرِي أَيْنَ تَذْهَبُ ‏\"‏‏.‏ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ‏.‏ قَالَ ‏\"‏ فَإِنَّهَا تَذْهَبُ حَتَّى تَسْجُدَ تَحْتَ الْعَرْشِ، فَتَسْتَأْذِنَ فَيُؤْذَنَ لَهَا، وَيُوشِكُ أَنْ تَسْجُدَ فَلاَ يُقْبَلَ مِنْهَا، وَتَسْتَأْذِنَ فَلاَ يُؤْذَنَ لَهَا، يُقَالُ لَهَا ارْجِعِي مِنْ حَيْثُ جِئْتِ‏.‏ فَتَطْلُعُ مِنْ مَغْرِبِهَا، فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ ‏}‏‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4802","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4802","x":"Narrated Abu Dharr:\n\nOnce I was with the Prophet (ﷺ) in the mosque at the time of sunset. The Prophet (ﷺ) said, \"O Abu Dharr! Do you know where the sun sets?\" I replied, \"Allah and His Apostle know best.\" He said, \"It goes and prostrates underneath (Allah's) Throne; and that is Allah's Statement:-- 'And the sun runs on its fixed course for a term (decreed). And that is the decree of All-Mighty, the All-Knowing....' (36.38)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا الأَعْمَشُ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ ـ رضى الله عنه ـ قَالَ كُنْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي الْمَسْجِدِ عِنْدَ غُرُوبِ الشَّمْسِ فَقَالَ ‏\"‏ يَا أَبَا ذَرٍّ أَتَدْرِي أَيْنَ تَغْرُبُ الشَّمْسُ ‏\"‏‏.‏ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ‏.‏ قَالَ ‏\"‏ فَإِنَّهَا تَذْهَبُ حَتَّى تَسْجُدَ تَحْتَ الْعَرْشِ، فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ‏}‏‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4803","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4803","x":"Narrated Abu Dharr:\n\nI asked the Prophet (ﷺ) about the Statement of Allah:-- 'And the sun runs on fixed course for a term (decreed), ' (36.38) He said, \"Its course is underneath \"Allah's Throne.\" (Prostration of Sun trees, stars. mentioned in Qur'an and Hadith does not mean like our prostration but it means that these objects are obedient to their Creator (Allah) and they obey for what they have been created for).","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ، قَالَ سَأَلْتُ النَّبِيَّ صلى الله عليه وسلم عَنْ قَوْلِهِ تَعَالَى ‏{‏وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا‏}‏ قَالَ ‏\"‏ مُسْتَقَرُّهَا تَحْتَ الْعَرْشِ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7424","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7424","x":"Narrated Abu Dharr:\n\nI entered the mosque while Allah's Messenger (ﷺ) was sitting there. When the sun had set, the Prophet (ﷺ) said, \"O Abu Dharr! Do you know where this (sun) goes?\" I said, \"Allah and His Apostle know best.\" He said, \"It goes and asks permission to prostrate, and it is allowed, and (one day) it, as if being ordered to return whence it came, then it will rise from the west.\" Then the Prophet (ﷺ) recited, \"That: \"And the sun runs on its fixed course (for a term decreed),\" (36.38) as it is recited by `Abdullah.","ar":"حَدَّثَنَا يَحْيَى بْنُ جَعْفَرٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ ـ هُوَ التَّيْمِيُّ ـ عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ، قَالَ دَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللَّهِ صلى الله عليه وسلم جَالِسٌ، فَلَمَّا غَرَبَتِ الشَّمْسُ قَالَ ‏\"‏ يَا أَبَا ذَرٍّ هَلْ تَدْرِي أَيْنَ تَذْهَبُ هَذِهِ ‏\"‏‏.‏ قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ‏.‏ قَالَ ‏\"‏ فَإِنَّهَا تَذْهَبُ تَسْتَأْذِنُ فِي السُّجُودِ فَيُؤْذَنُ لَهَا، وَكَأَنَّهَا قَدْ قِيلَ لَهَا ارْجِعِي مِنْ حَيْثُ جِئْتِ‏.‏ فَتَطْلُعُ مِنْ مَغْرِبِهَا ‏\"‏‏.‏ ثُمَّ قَرَأَ ‏{‏ذَلِكَ مُسْتَقَرٌّ لَهَا‏}‏ فِي قِرَاءَةِ عَبْدِ اللَّهِ‏.‏","v":[]}]};